package main
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"sort";"google.golang.org/protobuf/proto";"google.golang.org/protobuf/types/descriptorpb")
func hash(b []byte)string{v:=sha256.Sum256(b);return hex.EncodeToString(v[:])}
func main(){ var first *descriptorpb.FileDescriptorSet; rows:=[]map[string]any{};for _,path:=range os.Args[1:]{b,e:=os.ReadFile(path);if e!=nil{panic(e)};s:=new(descriptorpb.FileDescriptorSet);if e=proto.Unmarshal(b,s);e!=nil{panic(e)};sort.Slice(s.File,func(i,j int)bool{return s.File[i].GetName()<s.File[j].GetName()});if first==nil{first=s}else if !proto.Equal(first,s){panic(fmt.Sprintf("descriptor content differs: %s",path))};c,e:= (proto.MarshalOptions{Deterministic:true}).Marshal(s);if e!=nil{panic(e)};rows=append(rows,map[string]any{"path":path,"raw_sha256":hash(b),"canonical_sorted_sha256":hash(c),"files":len(s.File),"equal_by_file_content":true})};b,e:=json.MarshalIndent(rows,"","  ");if e!=nil{panic(e)};fmt.Println(string(b))}
